//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Returns the delay before the retry following `attempt` (1-based).
    pub fn delay_for_retry(&self, attempt: u32) -> u64 {
        let exponent = attempt.saturating_sub(1);
        let delay = self.base_delay_ms.checked_shl(exponent).unwrap_or(u64::MAX);
        delay.min(self.max_delay_ms)
    }
}

