/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let mut attempt = 1;

    loop {
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() || attempt >= config.max_attempts => {
                return Err(error)
            }
            Err(_) => {
                sleeper.sleep_ms(config.delay_for_retry(attempt));
                attempt += 1;
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn transient() -> RetryError {
        RetryError::Transient("temporary".into())
    }

    #[test]
    fn retries_transient_errors_with_bounded_exponential_delays() {
        let config = RetryConfig { max_attempts: 4, base_delay_ms: 10, max_delay_ms: 25 };
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            if calls < 4 { Err(transient()) } else { Ok(()) }
        });

        assert_eq!(result, Ok(()));
        assert_eq!(calls, 4);
        assert_eq!(sleeper.sleeps, vec![10, 20, 25]);
    }

    #[test]
    fn stops_on_permanent_error() {
        let config = RetryConfig { max_attempts: 4, base_delay_ms: 10, max_delay_ms: 100 };
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            Err(RetryError::Permanent("invalid".into()))
        });

        assert_eq!(result, Err(RetryError::Permanent("invalid".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn returns_last_transient_error_at_attempt_limit() {
        let config = RetryConfig { max_attempts: 2, base_delay_ms: 7, max_delay_ms: 100 };
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            Err(transient())
        });

        assert_eq!(result, Err(transient()));
        assert_eq!(calls, 2);
        assert_eq!(sleeper.sleeps, vec![7]);
    }

    #[test]
    fn delay_calculation_saturates_before_shift_overflow() {
        let config = RetryConfig { max_attempts: u32::MAX, base_delay_ms: u64::MAX, max_delay_ms: 123 };
        assert_eq!(config.delay_for_retry(u32::MAX), 123);
    }
}

